 pub fn configure_fixture(&mut self,window:&mut Window,cx:&mut Context<Self>){self.fixture=true;self.form=None;self.fixture_input.update(cx,|state,cx|state.focus(window,cx));cx.notify();}
 pub fn fixture_report(&self,window:&Window,cx:&App)->serde_json::Value{serde_json::json!({"runtime_ui":"gpui","phase":"completed","window_opened":true,"pid":std::process::id(),"node_started":false,"controlled_fixture":true,"input_text":self.fixture_input.read(cx).value().to_string(),"submitted_text":self.fixture_submitted,"action_count":self.fixture_actions,"focused":self.fixture_input.read(cx).focus_handle().is_focused(window),"ime_verified":false})}
