 fn button(&self,id:impl Into<ElementId>,label:impl Into<SharedString>,command:Command,cx:&mut Context<Self>)->Button{Button::new(id).label(label).on_click(cx.listener(move|this,_,_,cx|this.send(command.clone(),cx)))}
 fn nav(&self,id:&'static str,label:&'static str,route:Route,cx:&mut Context<Self>)->Button{Button::new(id).label(label).ghost().on_click(cx.listener(move|this,_,_,cx|this.navigate(route.clone(),cx)))}
 fn open_editor(&self,id:impl Into<ElementId>,label:impl Into<SharedString>,editor:Editor,values:BTreeMap<&'static str,String>,cx:&mut Context<Self>)->Button{Button::new(id).label(label).on_click(cx.listener(move|this,_,window,cx|this.edit(editor.clone(),values.clone(),window,cx)))}
 fn ask(&self,id:impl Into<ElementId>,label:impl Into<SharedString>,command:Command,cx:&mut Context<Self>)->Button{Button::new(id).label(label).danger().on_click(cx.listener(move|this,_,_,cx|{this.confirmation=Some(command.clone());cx.notify();}))}
 fn selected_bot(&self)->Option<&Bot>{self.snapshot.bots.iter().find(|b|Some(&b.conversation_id)==self.selected.as_ref())}
