 fn submit_form(&mut self,window:&mut Window,cx:&mut Context<Self>){let Some(form)=&self.form else{return};let mut values=form.values(cx);let editor=form.editor.clone();let conversation_id=self.conversation_id();if matches!(&editor,Editor::Connect|Editor::ConnectLocal|Editor::CreateNetwork|Editor::Join|Editor::Recovery){let scope=self.credential_scope.clone();let read=cx.read_credentials(&scope);cx.spawn(async move|this,cx|{let passphrase=match read.await{Ok(Some((_,bytes)))=>match String::from_utf8(bytes){Ok(value)=>value,Err(_)=>{let _=this.update(cx,|this,cx|{this.notice=Some("系统凭证记录无效，身份保持锁定。".into());cx.notify();});return}},Ok(None)=>{let value=format!("{}{}",uuid::Uuid::new_v4(),uuid::Uuid::new_v4());let task=cx.update(|cx|cx.write_credentials(&scope,"client-key",value.as_bytes()));if task.await.is_err(){let _=this.update(cx,|this,cx|{this.notice=Some("系统安全存储不可用，未创建或解锁身份。请先启用系统钥匙串或凭证服务。".into());cx.notify();});return}value},Err(_)=>{let _=this.update(cx,|this,cx|{this.notice=Some("无法读取系统安全存储，身份保持锁定。".into());cx.notify();});return}};values.insert("passphrase".into(),passphrase);let _=this.update(cx,|this,cx|this.send(Command::Save{editor,values,conversation_id},cx));}).detach();}else{self.send(Command::Save{editor,values,conversation_id},cx);}if let Some(form)=&self.form{for field in &form.fields{if ["password","ticket","token"].contains(&field.key){field.state.update(cx,|state,cx|state.set_value("",window,cx));}}}}

 fn send_message(&mut self,window:&mut Window,cx:&mut Context<Self>){let Some(bot)=self.selected_bot()else{self.notice=Some("请先选择 Bot。".into());return};let bot_id=bot.bot_id.clone();let target=if self.target_kind==0{InputTarget::BotMain{bot_id}}else{let Some(target)=self.selected_target.clone()else{self.notice=Some("请明确选择消息目标。".into());return};target};
 let id=match target_conversation(&target,&self.snapshot,self.selected.as_deref()){Ok(id)=>id,Err(error)=>{self.notice=Some(error.to_string());return}};let draft=ComposerDraft{target,intent:self.intent,text:self.composer.read(cx).value().to_string(),attachments:self.attachments.clone(),expected_revision:self.target_revision};if let Err(error)=draft.validate(){self.notice=Some(error);return}self.sending=true;self.send(Command::Input{conversation_id:id,draft},cx);}
 fn shell_sidebar(&self,cx:&mut Context<Self>)->AnyElement{let p=self.palette();let mut side=div().w(px(210.)).h_full().flex_none().bg(p.sidebar).border_r_1().border_color(p.border).p_3().flex().flex_col().gap_2().child(div().px_3().py_4().text_lg().font_weight(FontWeight::SEMIBOLD).child("Vibeface"));for(id,title,route)in[("home","Bot",Route::Home),("inbox","待处理",Route::Inbox),("tasks","任务",Route::Tasks),("channels","频道",Route::Channels),("memory","记忆",Route::Memory),("schedules","计划",Route::Schedules),("devices","设备",Route::Devices)]{side=side.child(self.nav(id,title,route,cx));}side=side.child(div().flex_1());for(id,title,route)in[("connect","连接",Route::Connect),("node","本机 Node",Route::Node),("settings","设置",Route::Settings)]{side=side.child(self.nav(id,title,route,cx));}side.child(div().px_3().py_2().text_xs().text_color(p.muted).child(if self.snapshot.online{"网络在线"}else{"未连接"})).into_any_element()}
