 fn chat(&self,cx:&mut Context<Self>)->AnyElement{let mut header=div().flex().flex_wrap().gap_2().px_6().py_3().border_b_1().border_color(self.palette().border).child(self.nav("bot-settings","Bot 设置",Route::Bot,cx));if let Some(id)=self.conversation_id(){header=header.child(self.button("stop-reply","停止回复",Command::StopReply(id.clone()),cx)).child(self.button("read-context","查看当前上下文",Command::ScopeContext{conversation_id:id,target:self.selected_target.clone().unwrap_or_else(||InputTarget::BotMain{bot_id:self.selected_bot().map(|b|b.bot_id.clone()).unwrap_or_default()})},cx));}for work in &self.snapshot.conversation.works{header=header.child(self.button(SharedString::from(format!("work-detail-{}",work.work_id)),format!("查看工作 {}",work.title),Command::WorkDetail{conversation_id:self.conversation_id().unwrap_or_default(),work_id:work.work_id.clone()},cx));if !["finished","completed"].contains(&work.state.as_str()){header=header.child(self.button(SharedString::from(format!("stop-{}",work.work_id)),format!("停止工作 {}",work.title),Command::StopWork{conversation_id:self.conversation_id().unwrap_or_default(),work_id:work.work_id.clone()},cx));}}
 let list_state=self.timeline.list.clone();let timeline=list(list_state,cx.processor(|this,index,_,cx|this.timeline_row(index,cx))).flex_1().w_full();
 let mut targets=div().flex().flex_wrap().gap_2();for(index,label)in["Bot 主对话","任务","工作补充","例行计划","频道成员","频道任务"].iter().enumerate(){targets=targets.child(Button::new(SharedString::from(format!("target-{index}"))).label(*label).on_click(cx.listener(move|this,_,_,cx|{this.target_kind=index;this.selected_target=None;this.target_revision=None;cx.notify();})));}
 let mut intents=div().flex().gap_2();for(label,intent)in[("继续",InputIntent::Continue),("新任务",InputIntent::NewTask),("延后",InputIntent::Defer)]{intents=intents.child(Button::new(label).label(label).on_click(cx.listener(move|this,_,_,cx|{this.intent=intent;cx.notify();})));}
 let composer=div().flex().flex_col().gap_3().p_4().border_t_1().border_color(self.palette().border).child(targets).child(self.target_picker(cx)).child(intents).child(Textarea::new(&self.composer).h(px(110.)).aria_label("消息内容")).child(div().flex().gap_2().child(Button::new("attach").label("添加附件").on_click(cx.listener(|this,_,window,cx|this.pick_attachment(window,cx)))).child(Button::new("send").label("发送").primary().disabled(self.sending||!self.snapshot.writable||!self.snapshot.synced).on_click(cx.listener(|this,_,window,cx|this.send_message(window,cx))))).child(div().text_xs().child(format!("目标：{} · 意图：{:?} · {} 个附件",["Bot 主对话","任务","工作补充","例行计划","频道成员","频道任务"][self.target_kind],self.intent,self.attachments.len())));
 div().flex().flex_col().size_full().child(header).child(timeline).children(self.detail.iter().map(|(name,value)|self.row(name.clone(),value.clone()))).child(self.queued_inputs(cx)).child(composer).into_any_element()}
 fn timeline_row(&self,index:usize,cx:&mut Context<Self>)->AnyElement{let mut row=div().flex().flex_col().child(self.timeline.render_row(index));if let Some(message)=self.timeline.message(index){let text=message.text.clone();let mut actions=div().flex().flex_wrap().gap_2().px_6().pb_2().child(Button::new(SharedString::from(format!("copy-{}",message.message_id))).label("复制内容").on_click(move|_,_,cx|crate::host::platform::copy_text(cx,text.clone())));if let Some(conversation_id)=self.conversation_id(){for file in &message.attachments{let save=file.clone();let id=conversation_id.clone();actions=actions.child(self.button(SharedString::from(format!("preview-{}-{}",message.message_id,file.hash)),format!("预览 {}",file.name),Command::ArtifactPreview{conversation_id:conversation_id.clone(),file:file.clone(),offset:0},cx)).child(Button::new(SharedString::from(format!("download-{}-{}",message.message_id,file.hash))).label(format!("保存 {}",file.name)).on_click(cx.listener(move|this,_,_,cx|this.save_artifact(id.clone(),save.clone(),cx))));}}row=row.child(actions);}row.into_any_element()}
 fn save_artifact(&mut self,conversation_id:String,file:vibeface_protocol::workspace::Attachment,cx:&mut Context<Self>){let picker=crate::host::platform::choose_save_path(cx,&std::env::temp_dir(),&file.name);cx.spawn(async move|this,cx|{match picker.await{Ok(Some(path))=>{let _=this.update(cx,|this,cx|this.send(Command::ArtifactSave{conversation_id,file,path},cx));},Ok(None)=>{},Err(error)=>{let _=this.update(cx,|this,cx|{this.notice=Some(format!("保存对话框失败：{error}"));cx.notify();});}}}).detach();}
