 fn queued_inputs(&self,cx:&mut Context<Self>)->AnyElement{let mut rows=div().flex().flex_col().gap_2().px_4();for queued in self.snapshot.inputs.iter().filter(|q|Some(&q.conversation_id)==self.selected.as_ref()&&!q.cancelled){let mut row=div().flex().gap_2().child(format!("{} · {}",if queued.deferred{"已延后"}else{"等待执行"},queued.input.text));for(label,action)in[("释放",InputControl::Release),("取消",InputControl::Cancel),("移到末尾",InputControl::Move{before_message_id:None})]{row=row.child(self.button(SharedString::from(format!("queued-{}-{label}",queued.input.message_id)),label,Command::Workspace(WorkspaceCommand::ControlInput{message_id:queued.input.message_id.clone(),expected_event:queued.control_event.clone(),action}),cx));}row=row.child(self.open_editor(SharedString::from(format!("queued-edit-{}",queued.input.message_id)),"编辑输入",Editor::QueuedEdit(queued.clone()),BTreeMap::from([("text",queued.input.text.clone())]),cx));rows=rows.child(row);}rows.into_any_element()}
 fn target_picker(&self,cx:&mut Context<Self>)->AnyElement{
 let mut choices:Vec<(String,InputTarget,Option<u64>)>=vec![];
 match self.target_kind{1=>for task in &self.snapshot.tasks{choices.push((task.title.clone(),InputTarget::Task{task_id:task.task_id.clone()},Some(task.revision)));},2=>for work in &self.snapshot.conversation.works{choices.push((work.title.clone(),InputTarget::Work{work_id:work.work_id.clone()},None));},3=>if let Some(bot)=self.selected_bot(){for job in &self.snapshot.conversation.scheduler.scope_jobs{if let Scope::Routine{trigger}=&job.scope{choices.push((format!("例行任务 {trigger}"),InputTarget::Routine{bot_id:bot.bot_id.clone(),trigger:trigger.clone()},None));}}},4=>for channel in &self.snapshot.channels{for member in &channel.members{let name=self.snapshot.bots.iter().find(|b|&b.bot_id==member).map(|b|b.name.as_str()).unwrap_or(member);choices.push((format!("{} / {}",channel.title,name),InputTarget::ChannelMember{channel_id:channel.channel_id.clone(),bot_id:member.clone()},None));}},5=>for channel in &self.snapshot.channels{for task in &self.snapshot.tasks{if task.channel_id.as_ref()==Some(&channel.channel_id)&&channel.members.contains(&task.owner_bot){choices.push((format!("{} / {}",channel.title,task.title),InputTarget::ChannelTask{channel_id:channel.channel_id.clone(),task_id:task.task_id.clone(),bot_id:task.owner_bot.clone()},Some(task.revision)));}}},_=>{}}
 let mut picker=div().flex().flex_wrap().gap_2();for(index,(label,target,revision))in choices.into_iter().enumerate(){let selected=self.selected_target.as_ref()==Some(&target);picker=picker.child(Button::new(SharedString::from(format!("target-choice-{index}"))).label(if selected{format!("已选：{label}")}else{label}).on_click(cx.listener(move|this,_,_,cx|{this.selected_target=Some(target.clone());this.target_revision=revision;cx.notify();})));}picker.into_any_element()
 }
