 fn memory(&self,cx:&mut Context<Self>)->AnyElement{let mut page=self.page().child(self.open_editor("memory-create","新增记忆",Editor::Memory(None),BTreeMap::new(),cx));let settings=&self.snapshot.conversation.bot_settings;page=page.child(format!("暂存 {} 条，修改记忆采用当前版本比较，不覆盖并发修改。",settings.memory_staged_count.map(|n|n.to_string()).unwrap_or_else(||"数量未知".into())));for conflict in &settings.memory_sync_conflicts.items{page=page.child(self.row("记忆同步冲突",format!("{} · {} · {} 与 {}",conflict.memory_id,conflict.reason,conflict.losing_revision,conflict.winning_revision)).child(self.button(SharedString::from(format!("memory-conflict-{}",conflict.memory_id)),"读取当前版本并比较",Command::ReadMemory{conversation_id:self.conversation_id().unwrap_or_default(),memory_id:conflict.memory_id.clone()},cx)));}if settings.memory_sync_conflicts.has_more{page=page.child("还有未展示的同步冲突，请缩小范围后重新读取。");}for conflict in settings.memory_conflicts.as_deref().unwrap_or(&[]){page=page.child(self.row("记忆提交冲突",format!("{} · 预期 {} · 当前 {} · {}",conflict.memory_id,conflict.expected_revision,conflict.actual_revision,conflict.reason)));}for memory in &self.snapshot.conversation.bot_settings.memory{page=page.child(self.row(memory.text.clone(),format!("{} · 版本 {}",if memory.metadata.user_controlled{"用户保护"}else{"自动记忆"},memory.metadata.revision)).child(self.open_editor(SharedString::from(format!("memory-edit-{}",memory.memory_id)),"编辑并保护",Editor::Memory(Some(memory.clone())),BTreeMap::from([("text",memory.text.clone())]),cx)).child(self.ask(SharedString::from(format!("memory-delete-{}",memory.memory_id)),"删除记忆",Command::DeleteMemory{conversation_id:self.conversation_id().unwrap_or_default(),memory:memory.clone()},cx)));}page.into_any_element()}
